function remember(){if(campaign?.id)root.localStorage.setItem(selectionKey(),campaign.id);root.LeadIntelJourney?.refresh?.();}
async function navigate(step){if(root.LeadIntelCustomerNavigation?.openModule)return root.LeadIntelCustomerNavigation.openModule(step);if(root.LeadIntelJourney)return root.LeadIntelJourney.open?.(step);root.dispatchEvent(new root.CustomEvent('leadintel:open-module',{detail:{step,journeyStage:step}}));}
function button(action,label,extra=''){return '<button type="button" class="'+(action==='save'||action==='prepare'?'primary-btn':'secondary-btn')+'" data-campaign-action="'+action+'" '+(busy?'disabled':'')+' '+extra+'>'+label+'</button>';}
function mount(){const event=$('event-campaign-panel'),target=$('campaign-planning-host')||$('step-2')||d.querySelector('#step-1 .stage1-primary-action');if(!$('email-campaign-panel')&&(event||target)){const panel=d.createElement('details');panel.id='email-campaign-panel';panel.className='event-campaign-panel feature-focus email-campaign-panel planning-card';panel.innerHTML='<summary class="brand-identity-summary" tabindex="-1"><div class="brand-identity-intro"><div class="planning-card-label"><span class="eyebrow">Email Campaigns</span><span class="planning-optional">Optional</span></div><h3>Reach selected buyers and partners with personalised emails.</h3><p class="reference-value-lead">Use one company, import a list or let LeadIntel find prospects. Research recipients first or go straight to personalised messages.</p></div><button id="email-planning-open" class="brand-identity-toggle lookalike-build-btn planning-card-action" type="button" aria-controls="email-campaign-panel" aria-expanded="false"><span>Prepare campaign</span><span aria-hidden="true">→</span></button></summary><div class="planning-setup-head"><h3>Prepare email campaign</h3><button id="email-planning-close" class="secondary-btn" type="button">Back to overview</button></div><div data-campaign-setup></div>';if(event&&!event.closest('#event-setup-dialog'))event.after(panel);else if(target.id==='campaign-planning-host'||target.id==='step-2')target.append(panel);else target.before(panel);panel.querySelector(':scope > summary').addEventListener('click',event=>event.preventDefault());$('email-planning-open').onclick=()=>{panel.open=true;panel.querySelector('[data-campaign-field="name"]')?.focus({preventScroll:true});};$('email-planning-close').onclick=()=>{captureForm();panel.open=false;$('email-planning-open').focus();};panel.addEventListener('toggle',()=>panel.querySelector('#email-planning-open')?.setAttribute('aria-expanded',String(panel.open)));}
 if(event&&!event.closest('#event-setup-dialog')&&$('email-campaign-panel')&&event.nextElementSibling!==$('email-campaign-panel'))event.after($('email-campaign-panel'));
 for(const [id,step,title] of [['email-campaign-research',5,'Campaign research'],['email-campaign-messages',6,'Campaign writer'],['email-campaign-delivery',7,'Campaign delivery']])if(!$ (id)&&$('step-'+step)){const section=d.createElement('section');section.id=id;section.className='ec-stage';section.hidden=true;section.setAttribute('aria-label',title);$('step-'+step).prepend(section);}render();renderResearch();}
function model(){return formBuffer||{name:campaign?.name||'',objective:campaign?.objective||'',templateId:campaign?.templateId||'custom',mode:campaign?.mode||'personalized',subject:campaign?.subject||'Hello {{buyerCompany}}',body:campaign?.body||''};}
