function planningFields(){return '<div class="ec-columns"><label>Where should we start?<select data-campaign-plan="sourceChoice"><option value="provided" '+(planning.sourceChoice==='provided'?'selected':'')+'>Use my companies / contacts</option><option value="discover" '+(planning.sourceChoice==='discover'?'selected':'')+'>Find companies for me</option><option value="mixed" '+(planning.sourceChoice==='mixed'?'selected':'')+'>My companies + find more</option></select></label><label>Desired total companies<input data-campaign-plan="targetCount" type="number" min="1" max="50" value="'+planning.targetCount+'"></label><label>People per company<input data-campaign-plan="contactsPerCompany" type="number" min="1" max="4" value="'+planning.contactsPerCompany+'"></label><label>Research depth<select data-campaign-plan="researchDepth">'+[['quick','Quick Overview'],['basic','Market Research'],['deep','Deep Analysis']].map(([v,label])=>'<option value="'+v+'" '+(planning.researchDepth===v?'selected':'')+'>'+label+'</option>').join('')+'</select></label></div><p class="ec-note">'+(planning.eventCampaignId?'Event-linked audience. ':'')+'Company amount and recipient amount are separate: up to '+((planning.sourceChoice==='provided'?audienceIds().length:Math.max(audienceIds().length,planning.targetCount))*planning.contactsPerCompany)+' people. Your own companies stay available even with weak fit. System additions must qualify; shortfalls are reported.</p>';}
function templateFields(v){if(planning.eventCampaignId)return '<p>Event invitation · uses the saved event, current recipient and attendance evidence. Unknown attendance stays conditional. Missing meeting details must be completed before preparing invitations.</p>'+button('event-setup','Edit event details');return '<div class="ec-columns"><label>Template<select data-campaign-field="templateId"><option value="custom">Write a campaign template</option>'+templates.map(t=>'<option value="'+esc(t.id)+'" '+(t.id===v.templateId?'selected':'')+'>'+esc(t.name)+'</option>').join('')+'</select></label><label>Message mode<select data-campaign-field="mode"><option value="personalized" '+(v.mode==='personalized'?'selected':'')+'>Personalised template</option><option value="same" '+(v.mode==='same'?'selected':'')+'>Same wording · identity fields only</option></select></label></div>'+(v.templateId==='custom'?'<label>Subject template<input data-campaign-field="subject" maxlength="500" value="'+esc(v.subject)+'"></label><label>Message template<textarea data-campaign-field="body" rows="7" maxlength="12000" placeholder="Write your campaign message here. Use identity fields to personalise each copy.">'+esc(v.body)+'</textarea></label><small>Fields: {{firstName}}, {{buyerCompany}}, {{role}}, {{sender}}, {{sellerCompany}}; {{trigger}} requires verified evidence. Include your sender name.</small>':'<p>Uses your existing template and verified buyer facts. Approved core wording stays protected.</p>');}
function eventEvidence(member){if(!planning.eventCampaignId)return '';const a=member.draft?.attendance||{status:'unknown'};let safe='';try{const u=new URL(a.sourceUrl);if(u.protocol==='https:'&&!u.username&&!u.password)safe=u.href;}catch{}return '<aside class="ec-event-evidence"><strong>Attendance: '+(a.status==='confirmed'?'Person confirmed':a.status==='company'?'Company listed · person unconfirmed':'Unknown · conditional invitation')+'</strong>'+(safe?'<p><a href="'+esc(safe)+'" target="_blank" rel="noopener noreferrer">Review attendance source</a> · '+esc(a.checkedAt||'')+'</p><p>'+esc(a.excerpt||'')+'</p>':'<p>No supported participation evidence for this edition.</p>')+'</aside>';}
function readiness(m){return !m.email?'Email needed':m.emailStatus==='verified'||m.emailStatus==='public_confirmed'?'Ready':'Review needed';}
function templateMissing(c){return !!c&&c.templateId==='custom'&&!(String(c.subject||'').trim()&&String(c.body||'').trim())&&!c.selection?.eventCampaignId;}
function render(){const open=new Set([...d.querySelectorAll('#email-campaign-panel details[open],#email-campaign-messages details[open]')].map(n=>n.dataset.member||n.className));renderContent();for(const n of d.querySelectorAll('#email-campaign-panel details,#email-campaign-messages details'))if(open.has(n.dataset.member||n.className)||n.classList.contains('ec-assistant')&&assistantPreview)n.open=true;for(const n of d.querySelectorAll('#email-campaign-panel input,#email-campaign-panel select,#email-campaign-panel textarea,#email-campaign-messages input,#email-campaign-messages select,#email-campaign-messages textarea')){const locked=n.closest('[data-member]')&&campaign?.members.find(m=>m.contactId===n.closest('[data-member]').dataset.member);n.disabled=busy||Boolean(locked&&(locked.sequenceId||locked.sentAt))||n.matches('[data-campaign-company]')&&scopeMode!=='selected';}renderResearch();}
function renderContent(){const host=$('email-campaign-panel')?.querySelector('[data-campaign-setup]');if(!host)return;const ready=workspace&&bridge()?.session?.authenticated,v=model(),rows=recipients,ids=audienceIds();
 host.innerHTML='<p class="ec-note">Set the purpose and audience here. Write your messages in Step 6. Research is optional.</p><p data-campaign-status role="status">'+esc(status||(!ready?'Sign in to prepare a campaign.':''))+'</p>'+planningFields()+'<label>Saved campaigns<select data-campaign-field="saved" '+(busy?'disabled':'')+'><option value="">New campaign</option>'+campaigns.map(c=>'<option value="'+esc(c.id)+'" '+(campaign?.id===c.id?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select></label><div class="ec-columns"><label>Campaign name<input data-campaign-field="name" maxlength="100" value="'+esc(v.name)+'"></label><label>Purpose<textarea data-campaign-field="objective" maxlength="1000" rows="2" placeholder="What should this campaign achieve?">'+esc(v.objective)+'</textarea></label></div><div class="ec-actions">'+button('companies','Choose CRM companies')+'<label class="ec-upload">Import a company list<input type="file" data-campaign-file accept=".csv,text/csv" '+(busy?'disabled':'')+'></label></div><small>CSV: company, website. Optional: name, email, title. You can add contacts later.</small><details class="ec-add-company"><summary>Add a single company</summary><div class="ec-columns"><label>Company name<input data-campaign-company-name maxlength="180" value="'+esc(addCompanyName)+'"></label><label>Company website<input data-campaign-company-website type="url" placeholder="https://company.com" value="'+esc(addCompanyWebsite)+'"></label></div>'+button('add-company','Add company')+'</details><div class="ec-columns"><label>Company selection<select data-campaign-scope><option value="selected" '+(scopeMode==='selected'?'selected':'')+'>Selected companies</option><option value="first" '+(scopeMode==='first'?'selected':'')+'>First N companies</option><option value="all" '+(scopeMode==='all'?'selected':'')+'>Entire list</option></select></label>'+(scopeMode==='first'?'<label>Number of companies<input data-campaign-count type="number" min="1" max="500" value="'+scopeCount+'"></label>':'')+'</div><div class="ec-search"><input data-campaign-company-search placeholder="Search CRM companies" aria-label="Search campaign companies">'+button('company-search','Search')+'</div><p>'+ids.length+' companies selected'+(companyCursor!==null?' · more CRM companies available':'')+'.</p><div class="ec-recipients">'+companies.map(c=>'<label class="ec-recipient"><input type="checkbox" data-campaign-company="'+esc(c.companyId)+'" '+(ids.includes(c.companyId)?'checked':'')+' '+(busy||scopeMode!=='selected'?'disabled':'')+'><span><strong>'+esc(c.company)+'</strong><small>'+esc(c.domain)+' · '+(Number(c.contactCount)||0)+' saved contacts</small></span></label>').join('')+'</div>'+(companyCursor!==null?button('company-more','Load more companies'):'')+'<details class="ec-existing-contacts"><summary>Choose existing contacts (optional)</summary><div class="ec-actions">'+button('refresh','Refresh CRM contacts')+button('one-per-company','Select one per company')+button('clear','Clear contact selection')+'</div><div class="ec-search"><input data-campaign-search placeholder="Search company or decision-maker" aria-label="Search campaign recipients">'+button('search','Search')+'</div><p>'+selected.size+' contacts selected. Missing emails do not block writing.</p><div class="ec-recipients">'+rows.map(r=>'<label class="ec-recipient"><input type="checkbox" data-campaign-contact="'+esc(r.contactId)+'" '+(selected.has(r.contactId)?'checked':'')+' '+(busy?'disabled':'')+'><span><strong>'+esc(r.name)+' · '+esc(r.company)+'</strong><small>'+esc(r.title)+' · '+esc(r.email||'Email needed')+' · '+esc(r.emailStatus||'Unverified')+'</small></span></label>').join('')+'</div>'+(cursor!==null?button('more','Load more contacts'):'')+'</details><div class="ec-actions ec-routes">'+button('save',campaign?'Save campaign brief':'Save campaign brief',!ready?'disabled':'')+button('research','Research recipients first',!ready?'disabled':'')+button('direct','Go straight to campaign writer →',!ready?'disabled':'')+'</div><small>Both routes save this campaign. Research uses your connected tools; the shortcut makes no research calls. Neither route sends email.</small>';
 for(const field of d.querySelectorAll('[data-campaign-field]'))if(field.dataset.campaignField!=='saved')field.disabled=busy;
 const messages=$('email-campaign-messages'),delivery=$('email-campaign-delivery');if(!campaign){if(messages)messages.hidden=true;if(delivery)delivery.hidden=true;if($('email-campaign-research'))$('email-campaign-research').hidden=true;return;}
 if(messages){messages.hidden=false;const missing=campaign.members.filter(m=>!m.draft&&!m.sequenceId&&!m.sentAt).length;messages.innerHTML='<h3>Campaign writer · '+esc(campaign.name)+'</h3><p class="ec-note">'+esc(campaign.objective||'Set your campaign purpose in Setup.')+'</p><p>'+((campaign.companies||[]).length)+' selected companies · '+campaign.members.length+' contacts. '+campaign.members.filter(m=>!m.email).length+' need an email before sending.</p><div class="ec-actions">'+button('setup','Edit campaign brief')+button('audience','Refresh contacts for these companies')+button('buyers','Find or review decision-makers')+button('verify','Edit contacts in CRM')+'</div>'+templateFields(v)+'<div class="ec-actions">'+button('save','Save template & recipient selection')+'</div><details class="ec-writer-audience"><summary>Campaign recipients</summary><p>Select the people to write to. One contact per company is selected by default when contacts are first added; you can select more.</p><div class="ec-actions">'+button('one-per-company','Select one per company')+button('clear','Clear contact selection')+'</div>'+rows.filter(r=>(campaign.companies||[]).some(c=>c.companyId===r.companyId)).map(r=>'<label class="ec-recipient"><input type="checkbox" data-campaign-contact="'+esc(r.contactId)+'" '+(selected.has(r.contactId)?'checked':'')+' '+(busy?'disabled':'')+'><span><strong>'+esc(r.name)+' · '+esc(r.company)+'</strong><small>'+esc(r.email||'Email needed')+'</small></span></label>').join('')+'</details>'+assistantPanel()+'<p>'+campaign.members.length+' selected recipients · '+campaign.members.filter(m=>m.approvedAt).length+' approved. Each person has a separate message.</p><p role="status">'+esc(status)+'</p>'+(templateMissing(campaign)?'<p class="ec-note">Write and save the subject and message templates above before preparing messages.</p>':'')+'<div class="ec-actions">'+button('prepare','Prepare missing messages',!missing||templateMissing(campaign)?'disabled':'')+button('approve-all','Approve all reviewed drafts',!campaign.members.some(m=>m.draft&&!m.approvedAt)?'disabled':'')+button('delivery','Continue to Delivery',!campaign.members.some(m=>m.approvedAt)?'disabled':'')+'</div><label class="ec-review"><input type="checkbox" data-campaign-reviewed '+(busy?'disabled':'')+'> I reviewed the subjects, messages, recipients and factual claims.</label>'+campaign.members.map(m=>{const draft=editBuffers.get(m.contactId)||m.draft||{subject:'',message:''},locked=m.sequenceId||m.sentAt;return '<details class="ec-member" data-member="'+esc(m.contactId)+'"><summary>'+esc(m.name)+' · '+esc(m.company)+' <span>'+esc(editBuffers.has(m.contactId)?'Unsaved edits · approval needs review':m.status)+'</span></summary><p>'+esc(m.email||'Email needed')+' · '+esc(readiness(m))+'</p>'+eventEvidence(m)+'<label>Subject<input data-campaign-subject="'+esc(m.contactId)+'" maxlength="60" value="'+esc(draft.subject)+'" '+(locked||busy?'disabled':'')+'></label><label>Email<textarea data-campaign-body="'+esc(m.contactId)+'" rows="9" maxlength="12000" '+(locked||busy?'disabled':'')+'>'+esc(draft.message)+'</textarea></label><p class="ec-error">'+esc(m.error)+'</p><div class="ec-actions">'+button('save-message','Save edited message','data-contact="'+esc(m.contactId)+'" '+(locked?'disabled':''))+button('regenerate','Regenerate this recipient','data-contact="'+esc(m.contactId)+'" '+(locked?'disabled':''))+button('approve','Approve reviewed message','data-contact="'+esc(m.contactId)+'" '+(!m.draft||locked?'disabled':''))+'</div></details>';}).join('');}
 if(delivery){delivery.hidden=false;delivery.innerHTML='<h3>Campaign delivery · '+esc(campaign.name)+'</h3>'+(campaign.deliveryRecovery?'<p class="ec-note">'+(campaign.deliveryRecovery.expired?'Delivery was interrupted. Review mailbox and queue receipts before recovery. Unconfirmed submissions remain held.':'Campaign delivery is in progress. Refresh its status after it finishes.')+'</p>'+(campaign.deliveryRecovery.expired?button('recover-delivery','Review interrupted delivery'):'' ):'')+'<p>Manual sending uses your selected connected mailbox. Automatic campaign delivery uses Gmail and your existing schedule, confirmation rules and daily limits. Activate it separately in Delivery settings.</p><p role="status">'+esc(status)+'</p><div class="ec-actions">'+button('queue','Queue this campaign’s approved messages',campaign.deliveryRecovery||!campaign.members.some(m=>m.approvedAt&&!m.sequenceId&&!m.sentAt)?'disabled':'')+button('reload','Refresh delivery status')+button('settings','Open mailbox & scheduling settings')+button('verify','Review contacts in CRM')+'</div><label class="ec-review"><input type="checkbox" data-campaign-delivery-approved '+(busy?'disabled':'')+'> I authorise delivery of the approved messages in this campaign.</label><label>Manual sending mailbox<select data-campaign-mailbox><option value="gmail" '+(manualMailbox==='gmail'?'selected':'')+'>Gmail</option><option value="microsoft" '+(manualMailbox==='microsoft'?'selected':'')+'>Microsoft / Outlook</option></select></label><div class="ec-delivery-list">'+campaign.members.map(m=>'<div><strong>'+esc(m.name)+' · '+esc(m.company)+'</strong><small>'+esc(m.email)+' · '+esc(m.providerStatus==='accepted'?'Accepted by Microsoft':m.status)+'</small><p class="ec-error">'+esc(m.error)+'</p>'+(['failed','skipped'].includes(m.status)&&m.sequenceId?button('recover','Return held message to review','data-contact="'+esc(m.contactId)+'"'):'')+button('send','Send this approved email now','data-contact="'+esc(m.contactId)+'" '+(campaign.deliveryRecovery||!m.approvedAt||!m.email||m.sequenceId||m.sentAt?'disabled':''))+'</div>').join('')+'</div>';}}
function assistantPanel(){return '<details class="ec-assistant"><summary>Writing Assistant · selected recipient</summary><p>Ask for a new email or improvements. The proposal changes only the selected recipient’s working copy.</p><label>Recipient<select data-campaign-assistant-contact>'+campaign.members.filter(m=>!m.sequenceId&&!m.sentAt).map(m=>'<option value="'+esc(m.contactId)+'">'+esc(m.name)+' · '+esc(m.company)+'</option>').join('')+'</select></label><label>Your request<textarea data-campaign-assistant-instruction maxlength="4000" rows="3">'+esc(assistantInstruction)+'</textarea></label>'+button('assistant','Ask Writing Assistant',!campaign.members.length?'disabled':'')+(assistantPreview?'<section class="ec-assistant-preview"><p>'+esc(assistantPreview.reply)+'</p>'+(assistantPreview.draft?'<strong>'+esc(assistantPreview.draft.subject)+'</strong><p class="ec-draft-text">'+esc(assistantPreview.draft.message)+'</p>'+button('apply-assistant','Apply to this recipient'):'')+'<small>'+esc((assistantPreview.warnings||[]).join(' '))+'</small></section>':'')+'</details>';}
function renderResearch(){const host=$('email-campaign-research');if(!host)return;host.hidden=!campaign||route!=='research';if(host.hidden)return;host.innerHTML='<h3>Campaign research · '+esc(campaign.name)+'</h3><p>'+(campaign.companies||[]).length+' selected companies. Uses the existing company evidence and purchasing-fit research. Work runs in batches of five; each batch checks the company website and public evidence. Provider usage depends on available evidence and retries.</p><p role="status">'+esc(status)+'</p><div class="ec-actions">'+button('research-run',researchRunning?'Researching…':'Research selected companies',researchRunning?'disabled':'')+button('buyers','Review campaign buyers')+button('direct','Go to campaign writer →')+'</div><small>Review evidence and gaps below. Research never approves or sends campaign messages.</small>';}
function captureForm(){const host=d;if(!$('email-campaign-panel'))return;const v={...model()};for(const n of host.querySelectorAll('[data-campaign-field]'))if(n.dataset.campaignField!=='saved')v[n.dataset.campaignField]=n.value;formBuffer=v;}
async function operation(fn){if(busy)return;const token=generation;busy=true;render();try{await fn();if(token===generation)status=status||'Campaign saved.';}catch(e){if(token===generation)status=e.message;}finally{if(token===generation){busy=false;render();renderResearch();root.LeadIntelJourney?.refresh?.();}}}
async function loadRecipients(append=false,q=''){const value=await api.request('/recipients?q='+encodeURIComponent(q)+(append?'&cursor='+cursor:''));recipients=append?[...recipients,...(value.recipients||[])]:value.recipients||[];cursor=value.nextCursor??null;}
function useCampaign(value){value.companies||=[...new Map(value.members.map(m=>[m.companyId,{companyId:m.companyId,company:m.company,domain:m.domain||''}])).values()];campaign=value;selected=new Set(value.members.map(m=>m.contactId));selectedCompanies=new Set((value.companies||[]).map(c=>c.companyId));for(const c of value.companies||[])if(!companies.some(r=>r.companyId===c.companyId))companies.push(c);planning=P.normalize(value.selection||{});scopeMode=value.selection?.scopeMode||'selected';scopeCount=value.selection?.scopeCount||10;sourceMode=value.selection?.sourceMode||'crm';sourceCompanyIds=new Set(value.selection?.listCompanyIds||[]);if(sourceMode==='list'){companies=value.listCompanies?.length?value.listCompanies:value.companies;companyCursor=null;}route=value.route||'direct';formBuffer=null;formDirty=false;assistantPreview=null;remember();}
async function reload(){if(campaign)useCampaign((await api.request('/'+campaign.id)).campaign);campaigns=(await api.request('')).campaigns;}
function selectCompanyForContact(r){if(!r)return;selectedCompanies.add(r.companyId);if(sourceMode==='list')sourceCompanyIds.add(r.companyId);if(!companies.some(c=>c.companyId===r.companyId))companies.push({companyId:r.companyId,company:r.company,domain:r.domain||'',contactCount:1});scopeMode='selected';}
async function loadCompanies(append=false,q=''){sourceMode='crm';if(!append)companyQuery=q;const result=await api.request('/companies?q='+encodeURIComponent(companyQuery)+(append?'&cursor='+companyCursor:''));companies=append?[...companies,...(result.companies||[])]:result.companies||[];companyCursor=result.nextCursor??null;}
async function useImportedList(ids){if(sourceMode!=='list')sourceCompanyIds=new Set(selectedCompanies);for(const id of ids)sourceCompanyIds.add(id);sourceMode='list';companies=(await api.request('/company-list','POST',{companyIds:[...sourceCompanyIds]})).companies||[];companyCursor=null;}
async function loadAllCompanies(){while(companyCursor!==null){if(companies.length>=500)throw Error('A campaign supports at most 500 companies. Select a smaller group.');await loadCompanies(true);}if(companies.length>500)throw Error('Select at most 500 companies');}
async function refreshAudience(defaults=false){const result=await api.request('/'+campaign.id+'/audience');recipients=result.recipients||[];for(const m of campaign.members)if(!recipients.some(r=>r.contactId===m.contactId))recipients.push(m);cursor=null;if(defaults&&!selected.size){selected=new Set(P.contacts(recipients,planning.contactsPerCompany));if(selected.size){formBuffer={...model()};formDirty=true;}}if(result.truncated)status='More than 500 contacts found. Narrow the company selection.';}
async function openResearch(focus='companies'){await root.LeadIntelCampaignModuleLoader?.(6);if(!root.LeadIntelDiscoveryUI?.openCampaignResearch)throw Error('Campaign research could not load. Your campaign is saved.');const opened=await root.LeadIntelDiscoveryUI.openCampaignResearch(campaign.companies,{focus});if(!opened)throw Error('Complete your seller Profile and targeting answers before research. Your campaign is saved; you can still use the direct writer.');route='research';renderResearch();$('email-campaign-research')?.scrollIntoView?.({block:'start'});}
